const std=@import("std");const B=@import("experimental/physical_water_f64.zig");const K=@import("experimental/soil_root_kernel_f64.zig");
test "f64 scalar witnesses no binade cap"{var l=B.Ledger{};var source:f64=705.3308409072768;var target:f64=0.3145934339965976;const paid=B.transfer(&source,&target,0.25,&l).?;try std.testing.expectEqual(@as(f64,0.25),paid);try std.testing.expect(l.absolute<1e-12);var soil:f64=0.249;var surface:f64=1;const infiltrated=B.transfer(&surface,&soil,0.01,&l).?;try std.testing.expect(infiltrated>0.009999999 and soil>0.25);}
test "f64 root common source and finite storage"{const s=K.State{.soil=0.25,.vapor=220,.cohorts=.{.{.biomass=0.2,.support=0.04,.root_fraction=0.25},.{.biomass=0.2,.support=0.04,.root_fraction=0.25},.{},.{}}};const r=K.step(s,.{.dt=1440,.capacity=1,.conductance=10.0/86400.0,.demand=.{0.001,0.001,0,0},.exposure=.{1,1,0,0}}).?;try std.testing.expect(r.result.root_receipts[0]>0 and r.result.root_receipts[0]==r.result.root_receipts[1]);try std.testing.expect(r.ledger.absolute<1e-12);}
test "f64 random scalar offline witnesses"{var rng=std.Random.DefaultPrng.init(144);for(0..10000)|i|{const source=std.math.pow(f64,2,@floatFromInt(rng.random().intRangeAtMost(i32,-120,120)))*(1+rng.random().float(f64));const target=std.math.pow(f64,2,@floatFromInt(rng.random().intRangeAtMost(i32,-120,120)))*rng.random().float(f64);const want=source*rng.random().float(f64);var s=source;var t=target;var l=B.Ledger{};const paid=B.transfer(&s,&t,want,&l) orelse continue;try std.testing.expect(paid<=want and s>=0);std.debug.print("F64_RECEIPT {d} {d} {d} {d} {d} {d} {d} {d} {d}\n",.{i,source,target,want,s,t,paid,l.signed,l.envelope});}}
test "f64 all24 unequal roots and storage permutations"{const s=K.State{.soil=0.001,.vapor=220,.cohorts=.{.{.biomass=1,.support=0.4,.root_fraction=0.25,.storage_fraction=0.25,.water=0.1},.{.biomass=1,.support=0.3,.root_fraction=0.125,.storage_fraction=0.5,.water=0.2},.{.biomass=1,.support=0.2,.root_fraction=0.5,.storage_fraction=0.25,.water=0.3},.{.biomass=1,.support=0.1,.root_fraction=0.25,.storage_fraction=0.25,.water=0.1}}};const p=K.Params{.dt=1,.capacity=1,.conductance=1,.demand=.{0.1,0.2,0.3,0.4},.exposure=.{1,1,1,1}};const ref=K.step(s,p).?;var count:u32=0;for(0..4)|a|for(0..4)|b|for(0..4)|c|for(0..4)|d|{if(a==b or a==c or a==d or b==c or b==d or c==d)continue;const indices=[_]usize{a,b,c,d};var ss=s;var pp=p;for(indices,0..)|old,new|{ss.cohorts[new]=s.cohorts[old];pp.demand[new]=p.demand[old];}const r=K.step(ss,pp).?;try std.testing.expectEqual(ref.result.state.soil,r.result.state.soil);try std.testing.expectEqual(ref.result.state.vapor,r.result.state.vapor);for(indices,0..)|old,new|{try std.testing.expectEqualDeep(ref.result.state.cohorts[old],r.result.state.cohorts[new]);try std.testing.expectEqual(ref.result.root_receipts[old],r.result.root_receipts[new]);try std.testing.expectEqual(ref.result.store_receipts[old],r.result.store_receipts[new]);}count+=1;};try std.testing.expectEqual(@as(u32,24),count);}
test "f64 fixed111 real-value coverage"{const Fixture=struct{patch:usize,state:K.State,temperature:f64};const parsed=try std.json.parseFromSlice([]Fixture,std.testing.allocator,@embedFile("experimental/soil_actual_fixtures.json"),.{});defer parsed.deinit();var accepted:u32=0;var positive:u32=0;for(parsed.value)|f|for([_]f64{1,60,1440})|dt|{var p=K.Params{.dt=dt,.capacity=1,.infiltration_rate=1.0/1024.0,.conductance=1,.exposure=.{1,1,1,1},.temperature=f.temperature};for(f.state.cohorts,0..)|c,i|p.demand[i]=0.1*@max(0,c.biomass-c.support)*dt/86400;const r=K.step(f.state,p).?;accepted+=1;var flow:f64=0;for(r.result.root_receipts,r.result.store_receipts)|a,b|flow+=a+b;if(flow>0)positive+=1;try std.testing.expect(r.ledger.absolute<=r.ledger.envelope);std.debug.print("F64_ACTUAL patch={d} dt={d} flow={d} residual={d} envelope={d}\n",.{f.patch,dt,flow,r.ledger.signed,r.ledger.envelope});};try std.testing.expectEqual(@as(u32,111),accepted);std.debug.print("F64_COVERAGE accepted={d} positive={d}\n",.{accepted,positive});}
test "f64 invalid and overflowing derived flows refuse without mutation"{const s=K.State{.soil=1,.cohorts=.{.{.biomass=1,.support=1,.root_fraction=1},.{},.{},.{}}};const p=K.Params{.dt=std.math.floatMax(f64),.capacity=1,.conductance=std.math.floatMax(f64),.demand=.{1,0,0,0},.exposure=.{1,0,0,0}};try std.testing.expect(K.step(s,p)==null);try std.testing.expect(!std.math.isFinite(B.downProduct(std.math.floatMax(f64),2)));var source:f64=1;var target:f64=std.math.floatMax(f64);var ledger=B.Ledger{};const before=ledger;try std.testing.expect(B.transfer(&source,&target,1,&ledger)==null);try std.testing.expectEqual(@as(f64,1),source);try std.testing.expectEqual(std.math.floatMax(f64),target);try std.testing.expectEqualDeep(before,ledger);}
